// REQUIRES: riscv-registered-target
// RUN: %clang_cc1 -triple riscv64 -target-feature +v \
// RUN:   -target-feature +zvfhmin \
// RUN:   -target-feature +experimental-zvvmtls \
// RUN:   -O2 -emit-llvm %s -o - | FileCheck %s

// Order-preserving tile store, LMUL=1, every element type IME exposes at the
// Clang surface: i8/i16/i32/i64 and f16/f32/f64. SEW comes from vtype, so
// each maps to the same vmts.v pseudo with the matching IR overload.

#pragma clang riscv intrinsic zvvm_vector

#include <riscv_vector.h>

// CHECK-LABEL: define dso_local void @test_vmts_v_i8m1
// CHECK-SAME:    (ptr noundef writeonly captures(none) [[BASE:%.*]], i64 noundef [[LD:%.*]], <vscale x 8 x i8> [[V:%.*]], i64 noundef [[VL:%.*]]) {{.*}} {
// CHECK:         tail call void @llvm.riscv.vmts.nxv8i8.p0.i64(<vscale x 8 x i8> [[V]], ptr [[BASE]], i64 [[LD]], i64 [[VL]])
// CHECK-NEXT:    ret void
//
void test_vmts_v_i8m1(int8_t *base, size_t ld, vint8m1_t v, size_t vl) {
  __riscv_vmts_v_i8m1(base, ld, v, vl);
}

